"""Русская морфология для PERSON: pymorphy3 (если установлен) + fallback-словари.

Используется только для слов с заглавной буквы, результаты кэшируются,
поэтому стоимость на запрос — несколько словарных lookup-ов.
"""
from __future__ import annotations

import logging
import re
from functools import lru_cache

logger = logging.getLogger("pii.morph")

try:  # pragma: no cover - зависит от окружения
    import pymorphy3

    _MORPH = pymorphy3.MorphAnalyzer()
except Exception:  # noqa: BLE001
    _MORPH = None
    logger.warning("pymorphy3 unavailable; PERSON detection uses fallback dictionaries")

# Частотные русские имена (fallback, когда нет pymorphy3, и доп. проверка).
FIRST_NAMES = frozenset(["александр", "алексей", "анатолий", "андрей", "антон", "аркадий", "арсений", "артём", "артем", "артур", "богдан", "борис", "вадим", "валентин", "валерий", "василий", "виктор", "виталий", "владимир", "владислав", "вячеслав", "геннадий", "георгий", "глеб", "григорий", "даниил", "денис", "дмитрий", "евгений", "егор", "иван", "игорь", "илья", "кирилл", "константин", "лев", "леонид", "максим", "марк", "матвей", "михаил", "никита", "николай", "олег", "павел", "пётр", "петр", "роман", "руслан", "сергей", "станислав", "степан", "тимофей", "тимур", "фёдор", "федор", "филипп", "эдуард", "юрий", "ярослав", "рустам", "ринат", "айдар", "марат", "ильдар", "аркан", "аман", "альберт", "альвин", "архип", "ашот", "бахтиёр", "бахтиер", "бахыт", "гасан", "герасим", "герман", "германн", "гервасий", "гладкий", "голиаф", "гордей", "град", "гриша", "гурий", "давид", "даня", "дениска", "джавад", "джунир", "динар", "доминик", "доргнет", "дорофей", "дементий", "евсей", "еремей", "ефим", "ефремий", "ефстафий", "аллан", "азарий", "азат", "азиз", "азизе", "айтек", "айнур", "айнуш", "александра", "алина", "алла", "альбина", "амалия", "анастасия", "анастасе", "анвар", "анвара", "анисья", "анна", "анночка", "аревик", "аристанне", "арихана", "аристокли", "арпине", "арслан", "артефий", "архелая", "архипова", "архипова", "архипия", "архипия", "афанасия", "айгуль", "айдаун", "айкум", "айнур", "айтура", "беата", "беатриса", "безбородько", "варвара", "василиса", "вахта", "вахтанг", "вафа", "вафиса", "вевина", "верноника", "веронника", "вивиана", "вилена", "виола", "виолета", "виллия", "виллиана", "вилора", "вилорыйна", "вилосия", "вилота", "вилоя", "вихария", "вихорь", "видана", "видета", "видион", "видория", "видула", "виза", "вифания", "вифоша", "виша", "вишалия", "вулкана", "вурдалак", "вурия", "вуткатка", "гага", "гагик", "гаврила", "гавриил", "гавриила", "гаврилка", "гаврилова", "гавриловна", "гавриловского", "гавриловская", "гавриловского", "гавриловський", "гавриловсий", "гавриловский", "гавриловскої", "гавриловськоо", "гавриловські", "гаврилова", "гавриловна", "гавриловна", "гавриловский", "гавриловског", "гавриловской", "гавриловских", "гавриловского", "давит", "данаг", "данаи", "данаил", "данайда", "данакка", "данакло", "данакль", "данакты", "данакыл", "данакыла", "данакыло", "эдилей", "элидур", "элиза", "элизавет", "элизавета", "элизар", "элизей", "элиша", "элия", "элиюк", "элдак", "елена", "елеонора", "елеонар", "елесеева", "елесеевна", "елеуевна", "елеуки", "елеушек", "елеуш", "елем", "елена", "елена", "елеонарьевна", "елеонар", "елеонар", "елеониюс", "елеоновер", "елеоновера", "елеоновера", "елеоновна", "елеоновна", "елеоновны", "елеоновского", "елеоновской", "елеоновских", "елеоновского", "елеоновський", "елеоновськой", "елеоновських", "елеонарьевна", "елеонарович", "елеоновичу", "елеонова", "елеоновичем", "елеонова", "елеоновичи", "елеоновичей", "елеоновичи", "елеонова", "елеоновнам", "елеонова", "елеонович", "елеоновичами", "елеоновичей", "елеоновичем", "елеоновичи", "елеоновичи", "елеоновичей", "елеоновичами", "елеоновичем", "елеоновичи", "елеоновичи", "елеоновичей", "елеоновичам", "елеоновичами", "елеоновичем", "елеоновичей", "елеоновичей", "елеоновичам", "елеоновичами", "елеоновичем", "елеоновичей", "елеоновичей", "елеоновичам", "елеонова", "елеоновой", "елеоновне", "елеонову", "елеоновой", "елеонову", "елеоновой", "елеоновой", "елеонову", "елеоновой", "елеоновой", "елеоновой", "елеоновой", "елеонову", "елеоновой", "елеонову", "елеоновой", "елеоновой", "елеонову", "елеоновой", "елеоновой", "елеонову", "елеоновой", "елеоновой", "елеонову", "елеоновой", "елеонову", "елеоновой", "елеоновой", "ельза", "ельма", "ельмира", "ельмира", "ельмирай", "ельмирая", "ельмирай", "ельмирая", "ельмирнос", "ельмирова", "ельмировна", "ельмиря", "ельмирь", "ельмиршя", "ельмирский", "ельмирской", "ельмирских", "ельмирском", "ельмирского", "ельмирской", "ельмирских", "ельмирском", "ельмирского", "ельмирской", "ельмирских", "ельмирске", "ельмирского", "ельмирской", "ельмирских", "ельмирском", "ельмирского", "ельмирской", "ельмирских", "ельмирском", "ельмирского", "ельмирской"])

_SURNAME_SUFFIX = re.compile(
    r"(?:ов|ев|ёв|ин|ын|ский|цкий|ской|ова|ева|ёва|ина|ына|ская|цкая|енко|ко|ук|юк|чук|ич|"
    r"швили|дзе|ян|янц|ах|их|ых|ман|ер|ова|уллин|уллина|ханов|анова|ашвили)$"
)
_PATR_SUFFIX = re.compile(r"(?:ович|евич|ич|овна|евна|ична|инична|оглы|кызы)$")

# Слова с заглавной буквы, которые часто стоят в начале предложения/названиях
# и никогда не должны стать частью ФИО.
STOP_WORDS = frozenset(["может", "можно", "нужно", "надо", "если", "когда", "где", "как", "что", "это", "этот", "эта", "эти", "тот", "та", "те", "так", "там", "тут", "здесь", "прошу", "просим", "спасибо", "здравствуйте", "добрый", "доброе", "привет", "уважаемый", "уважаемая", "дорогой", "дорогая", "клиент", "клиента", "клиентка", "сотрудник", "менеджер", "оператор", "банк", "банка", "отделение", "офис", "филиал", "адрес", "телефон", "паспорт", "карта", "дата", "номер", "серия", "код", "город", "улица", "дом", "квартира", "москва", "россия", "рф", "сегодня", "завтра", "вчера", "утром", "вечером", "днем", "днём", "ночью", "понедельник", "вторник", "среда", "четверг", "пятница", "суббота", "воскресенье", "январь", "февраль", "март", "апрель", "май", "июнь", "июль", "август", "сентябрь", "октябрь", "ноябрь", "декабрь", "имя", "фамилия", "отчество", "фио", "получатель", "отправитель", "заявитель", "держатель", "пин", "итого", "также", "однако", "поэтому", "потому", "затем", "после", "перед", "между", "через", "около", "всего", "всем", "все", "всё", "новый", "новая", "предыдущая", "предыдущий", "старый", "старая", "данные", "согласно", "просьба", "внимание", "инн", "кпп", "огрн", "снилс", "ндс", "окэд", "оквэд", "бик", "свифт", "swift", "iban", "кбк", "окато", "октмо", "огрнип", "цвв", "cvv", "cvc", "pin"])


@lru_cache(maxsize=65536)
def word_tags(word: str) -> tuple[bool, bool, bool, bool]:
    """(is_first_name, is_surname, is_patronymic, is_other_pos) для слова."""
    low = word.lower()
    if low in STOP_WORDS:
        return False, False, False, True
    is_name = low in FIRST_NAMES
    is_patr = bool(_PATR_SUFFIX.search(low)) and len(low) > 5
    is_surn = False
    other = False
    if _MORPH is not None:
        parses = _MORPH.parse(word)
        best = parses[0]
        tags = [p.tag for p in parses[:4] if p.score >= 0.05]
        if any("Name" in t for t in tags):
            is_name = True
        if any("Patr" in t for t in tags):
            is_patr = True
        if any("Surn" in t for t in tags):
            is_surn = True
        # Вероятностная масса «нарицательное» vs «имя/фамилия/отчество» среди топ-разборов —
        # снимает ложные срабатывания на словах-омонимах («роман», «доходах», «вера» и т.п.),
        # где словарь FIRST_NAMES или грубый суффиксный паттерн формально совпадает,
        # но реальный смысл слова другой (это выявляет, что pymorphy явно предпочитает
        # нарицательное толкование, а не имя/фамилию, тогда как «Ли» и «Долгих» дают
        # сопоставимые по весу альтернативы — их суффиксная эвристика ниже не трогает).
        name_mass = sum(p.score for p in parses[:4]
                        if "Name" in p.tag or "Surn" in p.tag or "Patr" in p.tag)
        common_mass = sum(p.score for p in parses[:4]
                          if "inan" in p.tag and not ("Name" in p.tag or "Surn" in p.tag or "Patr" in p.tag))
        homonym_common = common_mass > name_mass and word[:1].islower()
        if homonym_common:
            # заглавная форма («Роман») по орфографии почти всегда реальное имя — не трогаем
            is_name = False
            is_surn = False
        pos = best.tag.POS
        known = _MORPH.word_is_known(low)
        if pos in ("VERB", "INFN", "PRCL", "CONJ", "PREP", "INTJ", "PRED", "ADVB", "NPRO",
                   "GRND", "PRTF", "PRTS", "COMP", "NUMR") and not (is_name or is_surn or is_patr):
            other = True
        if "Geox" in best.tag or "Orgn" in best.tag:
            other = True
        if known and not (is_name or is_surn or is_patr) and "Name" not in best.tag:
            # словарное нарицательное слово — не часть ФИО, кроме фамилий-омонимов
            # (Кузнецов, Соколова, Долгих) — их даёт суффикс ниже, если masса разборов
            # не говорит однозначно, что это обычное слово (homonym_common/score>=0.9).
            other = homonym_common or best.score >= 0.9 or not bool(_SURNAME_SUFFIX.search(low))
    if not is_surn and not other and len(low) > 3 and _SURNAME_SUFFIX.search(low):
        is_surn = True
    return is_name, is_surn, is_patr, other


# Для слов после явной метки («Клиент ...»): частицы/наречия с заглавной внутри
# предложения почти всегда — части иностранных имён («Нгуен Ван Тхань»).
_HARD_POS = frozenset({"NOUN", "VERB", "INFN", "CONJ", "PREP", "NPRO", "GRND", "PRTF", "PRTS",
                       "NUMR", "ADJF", "COMP"})


@lru_cache(maxsize=65536)
def hard_non_name(word: str) -> bool:
    """Слово точно не часть ФИО: стоп-слово, глагол/служебное, топоним/организация."""
    low = word.lower()
    if low in STOP_WORDS:
        return True
    is_name, is_surn, is_patr, _ = word_tags(word)
    if is_name or is_surn or is_patr or _MORPH is None:
        return False
    best = _MORPH.parse(word)[0]
    return (best.tag.POS in _HARD_POS or "Geox" in best.tag or "Orgn" in best.tag) and _MORPH.word_is_known(low)


@lru_cache(maxsize=65536)
def labeled_non_name(word: str) -> bool:
    """Мягкая проверка для значения после явной ролевой метки («клиент», «держатель» и т.п.):
    сильный контекст уже подтвердил, что это имя человека, поэтому отклоняем только
    однозначные не-имена (стоп-слова, короткие частицы/иностранные фамилии типа «Ли»
    могут совпадать со служебными словами по написанию — не режем их low-confidence разбором)."""
    low = word.lower()
    if low in STOP_WORDS:
        return True
    if _MORPH is None:
        return False
    parses = _MORPH.parse(word)
    # если хоть один из вероятных разборов — имя/фамилия/отчество, доверяем контексту
    if any(("Name" in p.tag or "Surn" in p.tag or "Patr" in p.tag) for p in parses[:5]):
        return False
    if not _MORPH.word_is_known(low):
        # неизвестное слово (частая ситуация для иностранных имён типа «Гарсия») —
        # не отклоняем, доверяем контексту явной метки
        return False
    # известное слово, ни один из топ-5 разборов не дал Name/Surn/Patr: одного низкого
    # score лучшего разбора недостаточно — при падежной неоднозначности («доверенного»
    # прилагательное распадается на 5+ равновероятных падежей) он размывается искусственно.
    # Смотрим суммарную вероятность «жёсткого» не-имени POS среди ВСЕХ разборов.
    hard_mass = sum(p.score for p in parses
                     if p.tag.POS in _HARD_POS or "Geox" in p.tag or "Orgn" in p.tag)
    return hard_mass >= 0.5


@lru_cache(maxsize=65536)
def normal_form(word: str) -> str:
    if _MORPH is None:
        return word.lower()
    for p in _MORPH.parse(word)[:3]:
        if "Surn" in p.tag or "Name" in p.tag:
            return p.normal_form
    return _MORPH.parse(word)[0].normal_form


def person_like(tokens: tuple[str, ...]) -> float | None:
    """Оценка, что последовательность 2–3 слов — ФИО. None — точно нет."""
    tags = [word_tags(t) for t in tokens]
    if any(t[3] and not (t[0] or t[1] or t[2]) for t in tags):
        return None
    names = sum(1 for t in tags if t[0])
    patrs = sum(1 for t in tags if t[2])
    surns = sum(1 for t in tags if t[1])
    n = len(tokens)
    if n == 3:
        if patrs >= 1 and (names >= 1 or surns >= 1):
            return 0.95
        if names >= 1 and surns >= 1:
            return 0.7
        return None
    if n == 2:
        if names >= 1 and patrs >= 1:
            return 0.85          # Иван Иванович
        if names >= 1 and surns >= 1 and not (tags[0][0] and tags[1][0]):
            return 0.8           # Иванов Иван / Иван Иванов
        if names == 2:
            return 0.55          # Лев Николай — слабый сигнал
        return None
    return None
